"""Explain return documentation, missing templates, shell context and pointer casts."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1581': ('답안지에 숫자를 적는다고 해도 “처음 숫자”를 묻는지 “계산 뒤 숫자”를 묻는지 알아야 해요. 생성기는 함수 종류에 맞게 이 설명도 골라 적어요.', '공통 반환 설명과 특별한 함수의 반환 설명을 구별합니다.', '시작 5에 2를 더하는 두 표를 만드세요. fetch_add_unless는 저장 7·반환 5, add_unless는 저장 7·반환 true예요. 금지 값은 0으로 두세요.', ['gen_desc_return은 반환값을 설명하는 공통 문장을 출력해요. 반환은 호출한 쪽에 돌려주는 답이에요. v이면 Nothing, 즉 반환값 없음이라는 문장을 만들어요.', 'F나 f는 fetch 계열이어서 original value, 즉 바꾸기 전 값을 설명해요. R은 updated value, 즉 바꾼 뒤 값을 설명해요. l은 읽은 값을 설명해요. 같은 정수 자료형이라도 반환의 기준 시점이 다를 수 있어요.', '모든 함수가 이 공통 분류만으로 설명되지는 않아요. bool은 참·거짓인데 무엇을 참이라고 하는지까지 알아야 하니까요. 조건이 있는 특별한 함수는 해당 문서 템플릿이 더 구체적인 설명을 만들어요.', 'add_unless의 문서 템플릿은 pfx라는 앞이름이 비었는지 봐요. fetch_가 없으면 desc_return을 “갱신했으면 true, 아니면 false”라는 문장으로 바꿔요. fetch_가 있으면 이전 값이라는 공통 설명을 유지해요.', '현재 5·더할 값 2·금지 값 0이라면 두 형태 모두 7을 저장해요. 하지만 fetch_add_unless는 5, add_unless는 true를 반환해요. 현재 값이 금지 값과 같으면 갱신하지 않고 실패 때의 순서 약속은 relaxed라는 설명도 양식에 있어요.', '따라서 반환 타입, 공통 설명, 함수별 조건 설명을 함께 읽어야 해요. 문서 생성은 실제 숫자를 바꾸는 일이 아니라 사용할 사람이 결과를 올바르게 해석하도록 글을 만드는 단계예요.'], [('meta F의 공통 반환 설명은 어느 값을 말하나요?', ['계산한 뒤의 새 값이에요', '계산하기 전의 원래 값이에요'], '정답은 두 번째예요. fetch의 F는 original value라는 설명을 만들어요. 새 값을 설명하는 R과 구별하세요.'), ('add_unless에 fetch_ 앞이름이 없으면 어떤 반환 설명을 쓰나요?', ['갱신했는지를 true·false로 알려 준다는 설명이에요', '언제나 이전 숫자 자체를 반환한다는 설명이에요'], '정답은 첫 번째예요. 특별한 템플릿이 앞이름이 빈 경우 반환 설명을 바꿔요. 저장이 7이라도 반환은 true일 수 있으므로 숫자와 조건의 답을 구별하세요.')]), 'os1582': ('설명서 양식을 못 찾았을 때 “설명 없음”이라는 메모만 남길 수도 있어요. 파일을 만드는 작업이 끝났다고 설명까지 다 채워졌다는 뜻은 아니에요.', '문서 양식 누락 처리와 쉘의 점 명령을 이해합니다.', '양식 경로 있음 → 변수 준비 → 양식 실행, 경로 없음 → No kerneldoc available 주석의 두 갈래를 그리세요.', ['gen_kerneldoc은 먼저 문서 템플릿을 찾아 경로를 tmpl에 담아요. 템플릿은 설명 글을 만드는 양식이고 경로는 그 파일의 위치예요. -z 검사는 문자열이 비어 있는지 보는 쉘 검사예요.', '경로가 비면 No kerneldoc available이라는 문구를 C 주석 모양으로 출력해요. 이 함수의 그 갈래에는 무조건 생성을 중단시키거나 컴파일 오류를 만드는 명령이 없어요. 설명이 빠졌다는 표시를 남기는 것이에요.', '경로가 있으면 gen_template_kerneldoc을 불러요. 그 함수는 이름, 타입, 인자, 반환 설명 등을 준비한 뒤 . ${template}를 실행해요. 앞의 점은 소수점이나 C의 멤버 접근 기호가 아니라 쉘 명령이에요.', '이 점 명령을 source라고도 불러요. 양식 파일의 명령들을 현재 쉘 문맥에서 실행하므로 준비한 변수들을 사용할 수 있어요. 양식을 점 명령으로 읽는 것 자체가 항상 완전히 독립된 새 프로세스를 만드는 것은 아니에요.', '$(...)로 출력 글자를 모으는 명령 치환과도 구별하세요. 다른 단계에서 명령 치환을 사용했더라도, 점 명령은 그 점 명령이 실행되는 쉘 문맥에서 파일 내용을 수행해요. 어디에서 실행되고 어떤 변수를 읽는지 따라가야 해요.', '출력 파일이 생겼는지와 필요한 설명이 모두 있는지는 별도로 확인해야 해요. No kerneldoc available은 완성된 해설을 대신하지 않아요. 양식은 실행할 쉘 코드이므로 학습에서는 고정 원문의 내용을 읽어 의미를 확인해요.'], [('문서 양식을 찾지 못하면 이 함수가 반드시 전체 생성을 중단시키나요?', ['네. 무조건 컴파일 오류를 생성해요', '아니요. 이 갈래는 설명이 없다는 주석을 출력해요'], '정답은 두 번째예요. 빈 경로 갈래에는 No kerneldoc available 주석 출력이 있어요. 생성 결과가 나왔다는 사실과 문서가 완성됐다는 사실을 구별하세요.'), ('점 명령으로 템플릿을 source하면 어떻게 실행하나요?', ['점 명령이 있는 현재 쉘 문맥에서 양식의 명령을 실행해요', '항상 변수도 공유하지 않는 별도의 새 프로세스에서만 실행해요'], '정답은 첫 번째예요. 그래서 앞서 준비한 설명 변수들을 양식에서 사용할 수 있어요. 점 명령과 명령 치환을 같은 것으로 읽으면 안 돼요.')]), 'os1583': ('함수에 건넨 쪽지보다 옆에 놓인 메모를 읽는 코드가 있을 수 있어요. 무엇을 읽는지는 설명 제목만 보지 말고 실제 명령에서 확인해야 해요.', '명시적으로 받은 인자와 호출 문맥의 변수 의존성을 구별합니다.', '주변 변수 meta=B, 함수에 건넨 인자 v를 따로 적으세요. gen_ret_stmt가 실제 읽는 곳은 ${meta}라고 화살표를 그리세요.', ['gen_ret_stmt의 주석에는 meta를 인자로 받는다고 적혀 있어요. 하지만 본문을 보면 $1을 local meta에 넣는 줄이 없어요. 실제 검사는 meta_has_ret "${meta}"예요.', '$1은 함수에 건넨 첫 인자이고 ${meta}는 meta라는 이름의 변수예요. 둘이 저절로 같은 것은 아니에요. 이 함수는 호출 문맥에서 보이는 meta 값을 읽는다는 점을 찾아야 해요.', '예를 들어 주변 meta를 B로 두고 gen_ret_stmt v를 부르면 실제 검사는 B로 해요. B는 반환값이 있는 분류라서 return이라는 글자와 공백을 출력해요. 전달한 v만 보고 빈 결과일 것이라고 예상하면 틀려요.', '정상 long 생성기의 호출자는 local meta에 현재 분류를 담고 그 문맥에서 gen_ret_stmt를 불러요. 이때 보이는 meta가 원하는 분류와 같으므로 필요한 출력이 나오는 흐름이에요. 이런 주변 변수 의존성을 동적 변수 문맥과 연결해 읽을 수 있어요.', '이 의존성을 찾았다고 정상 헤더의 모든 함수가 잘못 생성됐다는 뜻은 아니에요. 직접 다른 인자로 호출한 예시와 정상 호출 흐름을 구별해야 해요. 반대로 다른 곳에서 독립 도구처럼 재사용하면 주변 meta 때문에 예상과 다른 결과가 날 수 있어요.', '함수가 무슨 값을 쓰는지 보려면 입력을 받는 줄, 변수를 읽는 줄, 호출하는 곳을 함께 살펴보세요. 주석의 인자 목록만 보고 인자로만 결정되는 함수라고 판단하지 마세요. 여기의 return 출력은 C 코드 글자를 만드는 일이지 원자 연산을 실행하는 일이 아니에요.'], [('주변 meta=B인데 gen_ret_stmt v를 직접 호출하면 무엇을 출력하나요?', ['인자 v만 보므로 언제나 빈 출력이에요', '주변 meta=B를 읽어서 return 글자를 출력해요'], '정답은 두 번째예요. 본문은 $1이 아니라 ${meta}를 검사해요. B가 반환 분류에 들어 있으므로 return과 공백이 출력돼요.'), ('이 주변 변수 의존성만 보고 정상 long 생성기의 모든 wrapper가 틀렸다고 할 수 있나요?', ['아니요. 정상 호출은 현재 분류를 local meta에 둔 문맥에서 이 도우미를 불러요', '네. 이런 변수 참조가 하나라도 있으면 모든 wrapper가 틀려요'], '정답은 첫 번째예요. 실제 호출 문맥에서 어떤 meta가 보이는지를 봐야 해요. 직접 만든 다른 호출의 결과를 정상 생성 전체의 실패로 확대하면 안 돼요.')]), 'os1584': ('같은 위치를 가리키더라도 받는 쪽에 맞는 자료형 표시가 필요할 수 있어요. 하지만 표시를 바꾼다고 그 위치의 실제 자료가 새로 생기거나 크기가 바뀌지는 않아요.', '정수 포인터에만 붙이는 cast와 32·64비트 분기를 이해합니다.', 'p:old를 s64·atomic64에 넣으면 (s64 *)old, int·atomic에 넣으면 (int *)old가 되는 두 줄을 적으세요.', ['cast는 C에서 값을 특정 자료형으로 취급하도록 쓰는 표시예요. gen_cast는 그 표시를 만들어 주는 쉘 함수예요. 먼저 콜론 앞 타입 분류가 p인지 확인하고 p가 아니면 출력하지 않고 돌아가요.', 'p는 정수 저장 공간을 가리키는 포인터예요. p:old에서 old는 이름이고 p가 cast 대상인 이유예요. cv·v·i에는 이 도우미가 cast를 출력하지 않아요. 모든 인자 앞에 같은 표시를 붙이는 규칙이 아니에요.', 'p:old와 기본 정수 s64를 전달하면 gen_param_type이 s64 *를 만들고, gen_cast가 괄호로 감싸 (s64 *)를 출력해요. 이후 gen_args_cast가 이름 old를 붙여 (s64 *)old가 돼요.', '기본 정수가 int인 갈래에서는 (int *)old가 돼요. long 생성기는 CONFIG_64BIT 분기에 s64·atomic64를, 다른 분기에 int·atomic을 연결해요. try_cmpxchg가 예상 값 메모의 위치를 전달할 때 이 차이가 나타나요.', 'ABI는 코드들이 자료의 크기와 함수 호출 방식 등을 맞추는 약속이에요. 이 cast는 해당 커널 설정의 자료형 연결을 표현해요. 임의의 환경에서 크기가 다른 메모리를 cast만으로 알맞게 늘리거나 바꿀 수는 없어요.', '포인터가 오래전에 사라진 자료를 가리키면 cast가 그 자료를 되살리지도 않아요. 선언의 타입 연결과 실제 자료의 크기·수명은 함께 확인해야 해요. 두 분기를 소스로 읽은 것과 각각의 환경에서 실제 실행한 것은 다른 검증이에요.'], [('gen_cast는 모든 인자에 강제 자료형 표시를 출력하나요?', ['네. 값과 모든 포인터에 똑같이 붙여요', '아니요. 콜론 앞 분류가 p일 때만 출력해요'], '정답은 두 번째예요. 시작 조건에서 p가 아니면 돌아가요. 그래서 p:old와 i:old는 이름이 같아도 cast 출력이 달라요.'), ('64비트 backend로 연결할 때 try_cmpxchg의 예상 값 포인터는 어떤 타입 표시를 받나요?', ['s64 *예요', '항상 unsigned char *예요'], '정답은 첫 번째예요. 생성기가 64비트 갈래에 s64라는 기본 정수 이름을 넘기고 p 분류가 별표를 붙여요. 다른 갈래의 int *와 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_391.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
